  if(one(db.query("SELECT COUNT(*) FROM step_action_binding WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? AND kind='MODEL_CALL' AND input_sha256=? AND arguments_sha256=? AND tool_version=? AND lease_generation=? AND created_by=? AND origin_run_id=run_id AND origin_step_id=step_id AND origin_action_id=action_id",(r,n)->r.getInt(1),j.tenant(),j.run(),j.step(),action,j.inputHash(),b.requestHash(),b.model(),a.leaseGeneration(),j.actor()))!=1)bad();var model=deps.required("model");
