 public JsonNode status(TaskSourceVerifierRuntimeAdapter.Session session,String invocation)throws Exception {
  session.requireUnchanged();var b=records.byInvocation(session.authority().job().tenant(),invocation);requireSession(session,b.original().dependencies());contexts.requireRead(session.authority(),b.original().dependencies());var row=one(db.query("SELECT status,settlement_status FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2)),b.tenant(),invocation));
  var result=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("invocation_id",invocation).put("origin_action_id",b.action()).put("context_manifest_id",b.context()).put("model_config_revision",b.model()).put("execution_status",row.get(0)).put("settlement_status",row.get(1));for(String key:List.of("provider_request_id","result_artifact_id","result_sha256","failure_code"))result.putNull(key);
  if("SETTLED".equals(row.get(1))){var value=results.verifiedSettlement(b,invocation,schema.price(text(b.original().dependencies().required("model").required("definition").required("price_basis"),"version_id"),b.original().dependencies().required("price")),false);var object=objects.registered(b.tenant(),invocation,"MODEL_RESULT").orElseThrow();result.set("provider_request_id",value.output().required("provider_request_id"));result.put("result_artifact_id",object.artifact().artifactId()).put("result_sha256",object.artifact().sha256());if("error".equals(value.output().required("reason").path("kind").asText()))result.set("failure_code",value.output().required("reason").required("failure").required("code"));}
  SchemaCatalogue.fromClasspath().validate("model-stream",result,"InvocationStatus");return result;
 }
