 private Snapshot snapshot(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,TaskSourceVerifierRuntimeAuthority.Verified proof,RunTokenAuthority.ActionRequest action,String context)throws Exception {
  proof.requireUnchanged();var original=records.requireStored(worker.tenantId(),context);var binding=records.bind(original,action.actionId());var deps=original.dependencies();
  if(!a.formalWorker()||!"TASK".equals(a.formalProof().identity().executionKind())||!binding.actor().equals(a.actorId())||!binding.principal().equals(worker.principalId())||!binding.run().equals(worker.runId())||!binding.step().equals(worker.stepId())||!binding.generation().equals(worker.leaseGeneration().toString())||!text(deps,"worker_service_uri").equals(worker.serviceUri())||!actionId(context).equals(action.actionId())||!binding.requestHash().equals(action.argumentsSha256())||!binding.inputHash().equals(action.inputSha256())||!binding.model().equals(action.toolVersion())||!text(original.request(),"business_purpose").equals(action.purpose()))deny();
  var model=deps.required("model");if(!new PermissionProtocol.Scope(binding.tenant(),nullable(model,"project_id"),"CONFIGURATION",text(model,"config_id")).equals(action.scope()))deny();
  var sent=contexts.requireTransmission(a,proof,deps);var exact=schema.parse(new String(original.bytes(),StandardCharsets.UTF_8));var body=FormalInvocationSendPreparation.providerBody(model.required("definition"),original.request().required("request_parameters"),exact);
  return new Snapshot(binding,model.deepCopy(),body,sent,schema.hash(sent),schema.price(text(model.required("definition").required("price_basis"),"version_id"),deps.required("price")));
 }
