 /** Rechecks a persisted review's original provenance under the current AT07 admission.
  * This factual check does not mint a Terminal, export proof, or a new model call. */
 public void requireSavedProvenance(TaskSourceVerifierRuntimeAuthority.Verified current,JsonNode provenance)throws Exception {
  current.requireUnchanged();if(!"N05".equals(text(provenance,"node_kind"))||!current.input().inputSha256().equals(text(provenance,"input_sha256"))||!current.input().receiptSha256().equals(text(provenance,"input_receipt_sha256")))bad();
  String session=text(provenance,"session_id");var original=terminalFacts(current.job(),session,provenance.required("invocations"));var supervision=provenance.required("supervision");
  if(!session.equals(text(supervision,"session_id"))||!original.binding.original().dependencies().required("host_binding").equals(supervision.required("binding"))||!current.leaseGeneration().toString().equals(original.binding.generation()))bad();
  if(!original.binding.original().dependencies().required("prompt_compilation").required("review_content").equals(provenance.required("independent_reads")))bad();
  contexts.requireRead(current,original.binding.original().dependencies());supervisors.requireClosedOriginal(current,supervision);current.requireUnchanged();
 }


 /** Factual original verification only: no current lease, source-read grant, or model execution. */
 public void requireOriginalProvenance(TaskSourceVerifierDispatchJournal.Original original,JsonNode provenance)throws Exception {
  original.requireUnchanged();var d=original.dispatch();var ref=original.reference();var envelope=original.envelope();var launch=original.launch();String actor=original.admission().actorId();
  if(!"N05".equals(text(provenance,"node_kind"))||!d.inputSha256().equals(text(provenance,"input_sha256"))||!text(envelope,"input_receipt_sha256").equals(text(provenance,"input_receipt_sha256")))bad();
  var job=one(db.query("SELECT r.task_id,p.principal_id,r.classification,r.created_at FROM task_run r JOIN run_principal p ON p.tenant_id=r.tenant_id AND p.project_id=r.project_id AND p.run_id=r.run_id AND p.initiator_id=r.created_by WHERE r.tenant_id=? AND r.project_id=? AND r.run_id=? AND r.created_by=? AND r.execution_kind='TASK' LIMIT 2 FOR UPDATE",(r,n)->new TaskSourceVerifierRuntimeAuthority.Job(ref.tenantId(),ref.projectId(),r.getString(1),d.runId(),d.stepId(),actor,r.getString(2),d.inputSha256(),r.getString(3),r.getTimestamp(4).toLocalDateTime()),ref.tenantId(),ref.projectId(),d.runId(),actor));
  if(!job.task().equals(text(envelope,"task_id")))bad();String session=text(envelope,"session_id");if(!session.equals(text(provenance,"session_id")))bad();
  var facts=terminalFacts(job,session,provenance.required("invocations"));var deps=facts.binding.original().dependencies();var supervision=provenance.required("supervision");
  if(!Long.toString(d.leaseGeneration()).equals(facts.binding.generation())||!launch.required("binding").equals(deps.required("host_binding"))||!launch.required("binding").equals(supervision.required("binding"))||!text(envelope,"input_receipt_sha256").equals(text(deps,"input_receipt_sha256"))||!text(envelope,"worker_service_uri").equals(text(deps,"worker_service_uri"))||!text(envelope,"action_id").equals(text(deps,"host_action_id"))||!text(launch,"deployment_sha256").equals(text(deps,"deployment_sha256"))||!text(deps,"supervision_receipt_id").equals(text(supervision,"admitted_receipt_id"))||!text(deps,"supervision_sha256").equals(text(supervision,"admitted_sha256")))bad();
  var readPins=deps.required("prompt_compilation").required("review_content");if(!readPins.equals(provenance.required("independent_reads")))bad();contexts.requireOriginalReadPins(original,readPins);
  supervisors.requireClosedOriginal(original,supervision);original.requireUnchanged();
 }
